from pathlib import Path
import json,shutil,html
P=Path(__file__).resolve().parent;R=P.parents[1];A=P/'slides/assets';A.mkdir(parents=True,exist_ok=True)
ref=R/'art-carousel-projects/festive-dispatch-preahvihear/slides/assets'
for src,name in [(ref/'cta-mascot.png','mascot-point.png'),(ref/'reveal-mascot.png','mascot-wave.png'),(ref/'fonts/Preahvihear-Regular.ttf','Preahvihear-Regular.ttf')]:shutil.copyfile(src,A/name)
slides=[
{'headline':['Supplier said Tuesday.',"It's Friday. ART's on it."],'body':['ART (A Realtime Tech) follows up','on overdue deliveries.']},
{'headline':['The delivery slipped.',"Your work shouldn't."],'body':['One late shipment can hold up','everything after it.']},
{'headline':['ART catches the missed date.'],'body':["It checks the expected delivery","against what's actually arrived."]},
{'headline':['"Any update?" Already sent.'],'body':['ART follows up with the supplier','for a revised delivery date.']},
{'headline':['A new date needs a clear answer.'],'body':["ART tracks the supplier's response","and updates the delivery status."]},
{'headline':['Still no answer? You hear about it.'],'body':['ART flags the delay and shows',"what's waiting on the shipment."]},
{'headline':['The chasing is handled.','The next call stays yours.'],'body':['Wait, escalate or explore another supplier','with the context in hand.']},
{'headline':['Keep work moving.','Let ART do the chasing.'],'body':['ART (A Realtime Tech) keeps delivery follow-ups',"off your team's to-do list."]}]
(P/'content.json').write_text(json.dumps({'topic':"Supplier said Tuesday. It's Friday.",'style':'Style 3','status':'Approach approved; draft copy and representative static design proof for review','slides':slides,'proof_slides':[1,4]},indent=2)+'\n')
css='''@font-face{font-family:Preahvihear;src:url(assets/Preahvihear-Regular.ttf);font-weight:400;font-display:block}*{box-sizing:border-box;margin:0;padding:0;font-family:Preahvihear;font-weight:400;font-style:normal;font-synthesis:none}html,body{width:1080px;height:1350px;background:#1A1A1A}.slide{position:relative;width:1080px;height:1350px;overflow:hidden;color:white}.photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.94) 0%,rgba(0,0,0,.88) 37%,rgba(0,0,0,.56) 48%,transparent 70%)}.bottom-shade{position:absolute;inset:0;background:linear-gradient(180deg,transparent 72%,rgba(0,0,0,.10) 78%,rgba(0,0,0,.82) 100%)}.copy{position:absolute;left:84px;right:84px;top:94px;z-index:4}.headline{font-size:76px;line-height:1.14;letter-spacing:-1px}.headline span{display:block}.aqua{color:#04ADC3}.body{font-size:36px;line-height:1.38;margin-top:28px}.prompt{display:table;max-width:912px;background:#04ADC3;color:#1A1A1A;border-radius:24px;font-size:28px;line-height:1.4;padding:18px 24px;margin-top:30px}.mascot{position:absolute;left:540px;top:555px;width:470px;height:470px;object-fit:contain;filter:drop-shadow(2px 5px 3px rgba(0,0,0,.22));z-index:3}.ground{position:absolute;left:650px;top:978px;width:280px;height:32px;border-radius:50%;background:radial-gradient(ellipse,rgba(0,0,0,.50),transparent 70%);z-index:2}.docket{position:absolute;left:120px;top:690px;width:355px;height:310px;background:#F6F0E5;border-radius:9px 9px 3px 3px;color:#1A1A1A;padding:28px 30px;box-shadow:9px 12px 15px rgba(0,0,0,.30),inset -6px 0 rgba(0,0,0,.07);transform:rotate(-3deg);z-index:2;border-top:13px solid #04ADC3}.docket:before{content:'';position:absolute;width:110px;height:28px;border-radius:5px;left:120px;top:-21px;background:linear-gradient(#DCE2DF,#889593)}.docket small{display:block;font-size:22px;color:#565C5C}.due{font-size:42px;line-height:1.3;margin-top:10px}.late{display:block;font-size:26px;line-height:1.35;padding-top:18px;margin-top:16px;border-top:2px solid #D6CEC0;color:#AD4141}.cover-result{position:absolute;left:84px;top:1090px;font-size:30px;line-height:1.4;color:white}.footer{position:absolute;left:84px;right:84px;bottom:92px;display:flex;justify-content:space-between;font-size:23px;z-index:5}.trail{position:absolute;left:84px;right:84px;bottom:38px;display:flex;gap:14px}.trail i{height:3px;background:rgba(255,255,255,.2);flex:1}.trail i.on{background:#04ADC3}.task .copy{top:105px}.task .headline{font-size:68px;line-height:1.15}.task .body{font-size:32px;line-height:1.4;margin-top:27px}.task .prompt{margin-top:30px}.task .mascot{left:505px;top:510px;width:510px;height:510px}.task .ground{left:640px;top:981px;width:290px}.phone{position:absolute;left:135px;top:613px;width:300px;height:388px;border-radius:35px;background:linear-gradient(125deg,#3E4B4E,#111A1C);padding:15px;box-shadow:9px 12px 12px rgba(0,0,0,.30);transform:rotate(-3deg);z-index:2}.screen{height:100%;background:#F4F2EC;border-radius:23px;color:#1A1A1A;padding:37px 19px 24px}.speaker{position:absolute;top:25px;left:112px;width:76px;height:8px;background:#26383B;border-radius:8px}.screen-title{font-size:23px;border-bottom:1px solid #C8D0CC;padding-bottom:17px}.message{font-size:25px;line-height:1.4;background:#DDF3F7;border-radius:17px 17px 4px 17px;margin-top:22px;padding:16px 16px}.sent{font-size:22px;margin-top:15px;display:flex;align-items:center;gap:10px;color:#286F5D}.sent svg{width:20px;height:20px;flex:none}.results{position:absolute;left:84px;right:84px;top:1082px;display:flex;gap:22px;z-index:4}.result{background:white;color:#1A1A1A;border-radius:20px;padding:20px 22px;font-size:25px;line-height:1.4;display:flex;gap:14px;align-items:center;flex:1}.result svg{width:25px;height:25px;flex:none}'''
tick='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12l5 5L20 5" fill="none" stroke="#2B907F" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'
clock='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="#8A6A22" stroke-width="2"/><path d="M12 6v6l4 2" fill="none" stroke="#8A6A22" stroke-width="2"/></svg>'
for n in [1,4]:
 s=slides[n-1]
 if n==1:
  title="<span>Supplier said Tuesday.</span><span>It's Friday.</span><span class='aqua'>ART's on it.</span>"
  prompt="Your team shouldn't have to chase."
  scene='''<div class="ground"></div><div class="docket"><small>EXPECTED DELIVERY</small><div class="due">Tuesday</div><div class="late">Friday.<br>Still not received.</div></div><img class="mascot" src="assets/mascot-point.png" alt="Original dimensional ART mascot pointing toward the overdue delivery record">'''
  result='<p class="cover-result">ART handles the follow-up.</p>'
 else:
  title='<span>"Any update?"</span><span class="aqua">Already sent.</span>'
  prompt='Ask for a date. Track the reply.'
  scene='''<div class="ground"></div><div class="phone"><div class="speaker"></div><div class="screen"><div class="screen-title">Supplier follow-up</div><div class="message">Please confirm<br>the revised<br>delivery date.</div><div class="sent">'''+tick+'''Follow-up sent</div></div></div><img class="mascot" src="assets/mascot-wave.png" alt="Original dimensional ART mascot making contact beside an outgoing supplier follow-up">'''
  result='<div class="results"><p class="result">'+tick+'Revised date requested.</p><p class="result">'+clock+'Supplier reply pending.</p></div>'
 doc='<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=1080,height=1350"><style>'+css+'</style></head><body><main class="slide '+('task' if n==4 else 'cover')+'"><img class="photo" src="assets/warehouse.png" alt="Illustrative modern goods receiving counter"><div class="shade"></div><div class="bottom-shade"></div><section class="copy"><h1 class="headline">'+title+'</h1><p class="body">'+'<br>'.join(html.escape(x) for x in s['body'])+'</p><p class="prompt">'+html.escape(prompt)+'</p></section>'+scene+result+'<footer class="footer"><span>@arealtimetech</span><span>'+f'{n:02d} / 08'+'</span></footer><div class="trail">'+''.join('<i class="'+('on' if i<n else '')+'"></i>' for i in range(8))+'</div></main></body></html>'
 (P/'slides'/f'slide-{n:02d}.html').write_text(doc)
print(P)
